package dev.shreyaspatil.debroid.jdi.eval

import dev.shreyaspatil.debroid.adb.DebugException
import dev.shreyaspatil.debroid.models.ErrorCode

/**
 * Represents tokens generated by [ExprLexer].
 */
sealed interface Token {
    // Literals
    data class IntLit(val value: Int) : Token
    data class LongLit(val value: Long) : Token
    data class FloatLit(val value: Float) : Token
    data class DoubleLit(val value: Double) : Token
    data class BooleanLit(val value: Boolean) : Token
    data class StringLit(val value: String) : Token
    data class CharLit(val value: Char) : Token
    data object NullLit : Token {
        override fun toString(): String = "NullLit"
    }

    // Identifiers & Keywords
    data class Ident(val name: String) : Token
    data object This : Token {
        override fun toString(): String = "This"
    }
    data object Super : Token {
        override fun toString(): String = "Super"
    }
    data object Is : Token {
        override fun toString(): String = "Is"
    }
    data object NotIs : Token {
        override fun toString(): String = "NotIs"
    }
    data object InstanceOf : Token {
        override fun toString(): String = "InstanceOf"
    }
    data object As : Token {
        override fun toString(): String = "as"
    }
    data object AsSafe : Token {
        override fun toString(): String = "as?"
    }

    // Operators
    data object AndAnd : Token { override fun toString(): String = "&&" }
    data object OrOr : Token { override fun toString(): String = "||" }
    data object Bang : Token { override fun toString(): String = "!" }
    data object EqEq : Token { override fun toString(): String = "==" }
    data object BangEq : Token { override fun toString(): String = "!=" }
    data object Lt : Token { override fun toString(): String = "<" }
    data object LtEq : Token { override fun toString(): String = "<=" }
    data object Gt : Token { override fun toString(): String = ">" }
    data object GtEq : Token { override fun toString(): String = ">=" }
    data object Plus : Token { override fun toString(): String = "+" }
    data object Minus : Token { override fun toString(): String = "-" }
    data object Star : Token { override fun toString(): String = "*" }
    data object Slash : Token { override fun toString(): String = "/" }
    data object Percent : Token { override fun toString(): String = "%" }
    data object Amp : Token { override fun toString(): String = "&" }
    data object Pipe : Token { override fun toString(): String = "|" }
    data object Caret : Token { override fun toString(): String = "^" }
    data object Tilde : Token { override fun toString(): String = "~" }
    data object LtLt : Token { override fun toString(): String = "<<" }
    data object GtGt : Token { override fun toString(): String = ">>" }
    data object GtGtGt : Token { override fun toString(): String = ">>>" }
    data object QuestionDot : Token { override fun toString(): String = "?." }
    data object QuestionColon : Token { override fun toString(): String = "?:" }

    // Punctuation
    data object Dot : Token { override fun toString(): String = "." }
    data object Comma : Token { override fun toString(): String = "," }
    data object Question : Token { override fun toString(): String = "?" }
    data object Colon : Token { override fun toString(): String = ":" }
    data object LParen : Token { override fun toString(): String = "(" }
    data object RParen : Token { override fun toString(): String = ")" }
    data object LBracket : Token { override fun toString(): String = "[" }
    data object RBracket : Token { override fun toString(): String = "]" }

    // End of input
    data object Eof : Token { override fun toString(): String = "EOF" }
}

/**
 * Wraps a [Token] with its 0-indexed character offset [position] in the input source.
 */
data class TokenPos(val token: Token, val position: Int)

/**
 * Tokenizer for expression strings in Debroid.
 *
 * Scans literals (integers, floats, doubles, longs, strings, chars, booleans, null),
 * identifiers (including backticked identifiers like `` `special-prop` ``),
 * keywords (`this`, `super`, `is`, `!is`, `instanceof`),
 * and operators (`&&`, `||`, `?.`, `?:`, `>>>`, `==`, etc.).
 */
class ExprLexer(private val input: String) {
    private var index = 0
    private val length = input.length

    /**
     * Converts the input string into a list of [TokenPos], ending with [Token.Eof].
     */
    fun tokenize(): List<TokenPos> {
        val tokens = mutableListOf<TokenPos>()
        while (index < length) {
            skipWhitespace()
            if (index >= length) break

            val startPos = index
            val token = nextToken()
            tokens.add(TokenPos(token, startPos))
        }
        tokens.add(TokenPos(Token.Eof, index))
        return tokens
    }

    private fun skipWhitespace() {
        while (index < length && input[index].isWhitespace()) {
            index++
        }
    }

    @Suppress("CyclomaticComplexMethod")
    private fun nextToken(): Token {
        val c = input[index]

        return when {
            c == '`' -> readBacktickedIdent()
            c == '"' -> readStringLiteral()
            c == '\'' -> readCharLiteral()
            c.isDigit() || isFractionalStart() -> readNumber()
            c.isJavaIdentifierStart() -> readIdentifierOrKeyword()
            else -> readOperatorOrPunctuation()
        }
    }

    /**
     * Checks if the current character starts a fractional literal (e.g., `.5` or `.123`).
     */
    private fun isFractionalStart(): Boolean =
        index < length && input[index] == '.' && index + 1 < length && input[index + 1].isDigit()

    private fun readBacktickedIdent(): Token {
        index++ // skip opening `
        val start = index
        while (index < length && input[index] != '`') {
            index++
        }
        if (index >= length) {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Unclosed backtick identifier at $start")
        }
        val name = input.substring(start, index)
        index++ // skip closing `
        return Token.Ident(name)
    }

    private fun readStringLiteral(): Token {
        index++ // skip opening "
        val sb = StringBuilder()
        while (index < length && input[index] != '"') {
            if (input[index] == '\\') {
                index++
                if (index >= length) {
                    throw DebugException(ErrorCode.EVALUATION_FAILED, "Unexpected EOF in escape sequence")
                }
                sb.append(readEscapeSequence())
            } else {
                sb.append(input[index])
                index++
            }
        }
        if (index >= length) {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Unterminated string literal")
        }
        index++ // skip closing "
        return Token.StringLit(sb.toString())
    }

    private fun readCharLiteral(): Token {
        index++ // skip opening '
        if (index >= length) {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Unterminated character literal")
        }
        val charVal = if (input[index] == '\\') {
            index++
            readEscapeSequence()
        } else {
            val c = input[index]
            index++
            c
        }
        if (index >= length || input[index] != '\'') {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Unterminated character literal")
        }
        index++ // skip closing '
        return Token.CharLit(charVal)
    }

    @Suppress("MagicNumber")
    private fun readEscapeSequence(): Char {
        val c = input[index]
        index++
        return when (c) {
            'n' -> '\n'
            'r' -> '\r'
            't' -> '\t'
            'b' -> '\b'
            'f' -> '\u000C'
            '\\' -> '\\'
            '"' -> '"'
            '\'' -> '\''
            'u' -> {
                if (index + 4 > length) {
                    throw DebugException(ErrorCode.EVALUATION_FAILED, "Invalid unicode escape sequence")
                }
                val hex = input.substring(index, index + 4)
                index += 4
                hex.toIntOrNull(16)?.toChar()
                    ?: throw DebugException(ErrorCode.EVALUATION_FAILED, "Invalid unicode escape \\u$hex")
            }
            else -> c
        }
    }

    private fun isHexPrefix(): Boolean {
        if (index + 1 >= length || input[index] != '0') return false
        val next = input[index + 1]
        return next == 'x' || next == 'X'
    }

    private fun isBinaryPrefix(): Boolean {
        if (index + 1 >= length || input[index] != '0') return false
        val next = input[index + 1]
        return next == 'b' || next == 'B'
    }

    @Suppress("CyclomaticComplexMethod", "MagicNumber")
    private fun readNumber(): Token {
        if (isHexPrefix()) return readHexNumber()
        if (isBinaryPrefix()) return readBinaryNumber()

        val start = index
        var isFloating = false
        while (index < length && input[index].isDigit()) {
            index++
        }

        if (isFractionalStart()) {
            isFloating = true
            index++ // skip .
            while (index < length && input[index].isDigit()) {
                index++
            }
        }

        if (index < length && (input[index] == 'e' || input[index] == 'E')) {
            isFloating = true
            index++
            if (index < length && (input[index] == '+' || input[index] == '-')) {
                index++
            }
            while (index < length && input[index].isDigit()) {
                index++
            }
        }

        val suffix = if (index < length) input[index] else null
        val numStr = input.substring(start, index)

        return parseNumericValue(numStr, suffix, isFloating)
    }

    private fun readHexNumber(): Token {
        index += 2 // skip 0x
        val hexStart = index
        while (index < length && isHexDigit(input[index])) {
            index++
        }
        if (index == hexStart) {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Invalid hex literal")
        }
        val hexStr = input.substring(hexStart, index)
        return if (index < length && (input[index] == 'L' || input[index] == 'l')) {
            index++
            Token.LongLit(hexStr.toLong(16))
        } else {
            Token.IntLit(hexStr.toInt(16))
        }
    }

    private fun readBinaryNumber(): Token {
        index += 2 // skip 0b
        val binStart = index
        while (index < length && (input[index] == '0' || input[index] == '1')) {
            index++
        }
        if (index == binStart) {
            throw DebugException(ErrorCode.EVALUATION_FAILED, "Invalid binary literal")
        }
        val binStr = input.substring(binStart, index)
        return if (index < length && (input[index] == 'L' || input[index] == 'l')) {
            index++
            Token.LongLit(binStr.toLong(2))
        } else {
            Token.IntLit(binStr.toInt(2))
        }
    }

    private fun parseNumericValue(numStr: String, suffix: Char?, isFloating: Boolean): Token {
        return when (suffix) {
            'f', 'F' -> {
                index++
                Token.FloatLit(numStr.toFloat())
            }
            'd', 'D' -> {
                index++
                Token.DoubleLit(numStr.toDouble())
            }
            'l', 'L' -> {
                index++
                Token.LongLit(numStr.toLong())
            }
            else -> {
                if (isFloating) {
                    Token.DoubleLit(numStr.toDouble())
                } else {
                    Token.IntLit(numStr.toInt())
                }
            }
        }
    }

    private fun isHexDigit(c: Char): Boolean =
        c.isDigit() || (c in 'a'..'f') || (c in 'A'..'F')

    private fun readIdentifierOrKeyword(): Token {
        val start = index
        while (index < length && input[index].isJavaIdentifierPart()) {
            index++
        }
        val text = input.substring(start, index)
        return when (text) {
            "true" -> Token.BooleanLit(true)
            "false" -> Token.BooleanLit(false)
            "null" -> Token.NullLit
            "this" -> Token.This
            "super" -> Token.Super
            "is" -> Token.Is
            "instanceof" -> Token.InstanceOf
            "as" -> {
                // If followed immediately by '?', consume it as a single safe-cast token (as?)
                if (index < length && input[index] == '?') {
                    index++
                    Token.AsSafe
                } else {
                    Token.As
                }
            }
            else -> Token.Ident(text)
        }
    }

    @Suppress("CyclomaticComplexMethod", "LongMethod")
    private fun readOperatorOrPunctuation(): Token {
        val c = input[index]
        index++

        return when (c) {
            '.' -> Token.Dot
            ',' -> Token.Comma
            ':' -> Token.Colon
            '(' -> Token.LParen
            ')' -> Token.RParen
            '[' -> Token.LBracket
            ']' -> Token.RBracket
            '+' -> Token.Plus
            '-' -> Token.Minus
            '*' -> Token.Star
            '/' -> Token.Slash
            '%' -> Token.Percent
            '^' -> Token.Caret
            '~' -> Token.Tilde
            '?' -> readQuestion()
            '&' -> readAmpersand()
            '|' -> readPipe()
            '!' -> readBang()
            '=' -> readEquals()
            '<' -> readLessThan()
            '>' -> readGreaterThan()
            else -> throw DebugException(
                ErrorCode.EVALUATION_FAILED,
                "Unexpected character '$c' at position ${index - 1}"
            )
        }
    }

    private fun readQuestion(): Token {
        return when {
            index < length && input[index] == '.' -> {
                index++
                Token.QuestionDot
            }
            index < length && input[index] == ':' -> {
                index++
                Token.QuestionColon
            }
            else -> Token.Question
        }
    }

    private fun readAmpersand(): Token {
        return if (index < length && input[index] == '&') {
            index++
            Token.AndAnd
        } else {
            Token.Amp
        }
    }

    private fun readPipe(): Token {
        return if (index < length && input[index] == '|') {
            index++
            Token.OrOr
        } else {
            Token.Pipe
        }
    }

    private fun readBang(): Token {
        return when {
            index < length && input[index] == '=' -> {
                index++
                Token.BangEq
            }
            isNotIsKeyword() -> {
                index += 2
                Token.NotIs
            }
            else -> Token.Bang
        }
    }

    private fun isNotIsKeyword(): Boolean {
        if (index + 1 >= length || input[index] != 'i' || input[index + 1] != 's') return false
        val afterIs = index + 2
        return afterIs >= length || !input[afterIs].isJavaIdentifierPart()
    }

    private fun readEquals(): Token {
        if (index < length && input[index] == '=') {
            index++
            return Token.EqEq
        }
        throw DebugException(ErrorCode.EVALUATION_FAILED, "Unexpected assignment operator '=' in expression")
    }

    private fun readLessThan(): Token {
        return when {
            index < length && input[index] == '=' -> {
                index++
                Token.LtEq
            }
            index < length && input[index] == '<' -> {
                index++
                Token.LtLt
            }
            else -> Token.Lt
        }
    }

    private fun readGreaterThan(): Token {
        return when {
            index < length && input[index] == '=' -> {
                index++
                Token.GtEq
            }
            index + 1 < length && input[index] == '>' && input[index + 1] == '>' -> {
                index += 2
                Token.GtGtGt
            }
            index < length && input[index] == '>' -> {
                index++
                Token.GtGt
            }
            else -> Token.Gt
        }
    }
}
